mapper.select:
SELECT i.id, i.industry_code AS industryCode, i.parent_industry_code AS parentIndustryCode,
    i.industry_level AS level, i.name, i.description, i.default_mcc_code AS defaultMccCode,
    i.logo_file_address AS logoFileAddress, i.sort_no AS sortNo, i.status, i.version,
    i.create_time AS createTime, i.update_time AS updateTime
FROM t_ref_industry i
LEFT JOIN t_ref_industry p ON p.industry_code = i.parent_industry_code

    AND i.industry_level = #{level}
    AND i.parent_industry_code = #{parentCode}
    AND i.status = #{status}

        AND i.industry_code IN
        #{code}


ORDER BY COALESCE(p.sort_no, i.sort_no), COALESCE(p.industry_code, i.industry_code), i.industry_level,
    i.sort_no, i.industry_code
